// ASYNC
// --- returns [num actually tested, total secs]

export const testFilesMatching = async (
		pat: string,
		hOptions: hash = {}
		): AutoPromise<[number, number]> => {   // --- [# tested, secs]

	type opt = {
		quiet: boolean     // --- no output
		verbose: boolean   //     output even if not needed
		maxRunning: number
		}
	const {quiet, verbose, maxRunning} = getOptions<opt>(hOptions, {
		quiet: false,
		verbose: false,
		maxRunning: 8
		})

	assert(!(quiet && verbose), "Can't use both quiet and verbose")
	let nErr = 0
	let nProcessed = 0
	const timer = new CTimer()
	for await (const [ok, result] of allExecResults([doUnitTest, pat], hOptions)) {
		if (ok) {
			// --- result is a TExecResult
			const {infile, success, notNeeded} = result
			const prefix = `COMPILE ${infile}`
			if (notNeeded) {
				assert(success, "success true with notNeeded true")
				if (verbose) {
					console.log(f`${prefix} - ${'Not Needed'}:{yellow}`)
				}
			}
			else if (success) {
				nProcessed += 1
				if (!quiet) {
					console.log(f`${prefix} - ${'Succeeded'}:{green}`)
				}
			}
			else {
				if (!quiet) {
					console.log(f`${prefix} - ${'Failed'}:{red}`)
				}
			}
		}
		else {
			console.log(f`ERROR: ${result}:{red}`)
			nErr += 1
		}
	}
	if (nErr > 0) {
		croak("Some files failed to compile")
	}
	return [nProcessed, timer.timeTaken()]
}

